class CreditExhaustedError(Exception):
    """Raised when the 5-hour AI credit / quota limit or billing cap is reached."""


SYSTEM_PROMPT = f"""You are the Idea Factory Autonomous Venture Architect.
Synthesize a novel, high-margin, capital-efficient B2B SaaS or AI-Native Service product idea grounded in:
1. Claude_Skills_Project skills: {[s.name for s in CLAUDE_SKILLS_CATALOG]}
2. Business_Analyzer_Project NAICS sectors: {list(BUSINESS_ANALYZER_INDUSTRIES.keys())}
3. Workspace repositories: {list(WORKSPACE_PROJECTS.keys())}
4. Founder profile: {FOUNDER_EDGE_SUMMARY}

Return ONLY a valid JSON object matching the exact kwargs of `make_idea(...)`, with thorough 2-4 sentence quantitative answers for all 14 diligence fields.
"""


def active_provider() -> str:
    """Detect the highest-priority configured LLM provider, defaulting to 'synthesis'."""
    if config.IDEA_LLM_PROVIDER:
        return config.IDEA_LLM_PROVIDER
    if config.ANTHROPIC_API_KEY:
        return "anthropic"
    if config.GEMINI_API_KEY:
        return "gemini"
    if config.OPENAI_API_KEY:
        return "openai"
    if config.OPENROUTER_API_KEY:
        return "openrouter"
    return "synthesis"


def _check_credit_error(status_code: int, body_text: str) -> None:
    lower = body_text.lower()
    if status_code == 402 or any(
        kw in lower
        for kw in (
            "credit balance is too low",
            "insufficient_quota",
            "billing_hard_limit",
            "5-hour limit",
            "rate_limit_error",
            "quota exceeded",
            "out of credits",
        )
    ):
        raise CreditExhaustedError(f"HTTP {status_code}: AI credit/quota limit reached ({body_text[:240]})")


def _extract_json(text: str) -> dict[str, Any]:
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        start, end = text.find("{"), text.rfind("}")
        if start == -1 or end <= start:
            raise ValueError("Response contained no JSON object")
        return json.loads(text[start : end + 1])


def _call_llm_api(provider: str, user_prompt: str) -> dict[str, Any]:
    """Call Anthropic, Gemini, OpenAI, or OpenRouter, raising CreditExhaustedError on quota exhaustion."""
    if provider == "claude_cli":
        proc = subprocess.run(
            ["claude", "-p", f"{SYSTEM_PROMPT}\n\n{user_prompt}", "--output-format", "text"],
            capture_output=True,
            text=True,
            timeout=config.LLM_TIMEOUT_SECONDS,
        )
        if proc.returncode != 0:
            _check_credit_error(429, proc.stderr + proc.stdout)
            raise RuntimeError(f"claude CLI failed: {proc.stderr[:200]}")
        return _extract_json(proc.stdout)

    if provider == "anthropic":
        url = "https://api.anthropic.com/v1/messages"
        headers = {
            "x-api-key": config.ANTHROPIC_API_KEY,
            "anthropic-version": "2023-06-01",
            "content-type": "application/json",
        }
        payload = {
            "model": config.ANTHROPIC_MODEL,
            "max_tokens": 2800,
            "system": SYSTEM_PROMPT,
            "messages": [{"role": "user", "content": user_prompt}],
        }
    elif provider == "gemini":
        url = f"https://generativelanguage.googleapis.com/v1beta/models/{config.GEMINI_MODEL}:generateContent?key={config.GEMINI_API_KEY}"
        headers = {"content-type": "application/json"}
        payload = {
            "systemInstruction": {"parts": [{"text": SYSTEM_PROMPT}]},
            "contents": [{"parts": [{"text": user_prompt}]}],
            "generationConfig": {"responseMimeType": "application/json"},
        }
    elif provider == "openai":
        url = "https://api.openai.com/v1/chat/completions"
        headers = {"Authorization": f"Bearer {config.OPENAI_API_KEY}", "content-type": "application/json"}
        payload = {
            "model": config.OPENAI_MODEL,
            "response_format": {"type": "json_object"},
            "messages": [
                {"role": "system", "content": SYSTEM_PROMPT},
                {"role": "user", "content": user_prompt},
            ],
        }
    elif provider == "openrouter":
        url = "https://openrouter.ai/api/v1/chat/completions"
        models = [m.strip() for m in config.OPENROUTER_MODEL.split(",") if m.strip()]
        headers = {
            "Authorization": f"Bearer {config.OPENROUTER_API_KEY}",
            "content-type": "application/json",
            "X-Title": "Idea Factory 5Hr Loop",
        }
        payload = {
            **({"models": models} if len(models) > 1 else {"model": models[0]}),
            "messages": [
                {"role": "system", "content": SYSTEM_PROMPT},
                {"role": "user", "content": user_prompt},
            ],
        }
    else:
        raise ValueError(f"Unsupported API provider: {provider}")

    req = urllib.request.Request(
        url, data=json.dumps(payload).encode("utf-8"), headers=headers, method="POST"
    )
    try:
        with urllib.request.urlopen(req, timeout=config.LLM_TIMEOUT_SECONDS) as resp:
            body = json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        err_body = exc.read().decode("utf-8", errors="replace")
        _check_credit_error(exc.code, err_body)
        raise

    if provider == "anthropic":
        return _extract_json(body["content"][0]["text"])
    if provider == "gemini":
        return _extract_json(body["candidates"][0]["content"]["parts"][0]["text"])
    return _extract_json(body["choices"][0]["message"]["content"])


