def generate_next_idea(
    existing_ideas: list[ProductIdea],
    iteration: int = 0,
) -> tuple[ProductIdea, str, float]:
    """Generate the next non-duplicate ProductIdea using the active LLM provider or Synthesis Engine.

    Returns (idea, provider_used, estimated_cost_usd).
    Raises CreditExhaustedError if the configured AI provider hits its 5-hour credit/quota limit.
    """
    existing_ids = {i.id for i in existing_ideas}
    existing_slugs = {i.slug for i in existing_ideas}
    provider = active_provider()

    if provider != "synthesis":
        next_num = len(existing_ids) + 1
        while f"IDEA-{next_num:03d}" in existing_ids:
            next_num += 1
        prompt = (
            f"Generate ProductIdea id='IDEA-{next_num:03d}'. Do NOT duplicate any of these existing slugs: "
            f"{sorted(existing_slugs)}. Include all required fields for `make_idea(...)`."
        )
        raw = _call_llm_api(provider, prompt)
        raw["id"] = f"IDEA-{next_num:03d}"
        raw["generation_source"] = f"LLM_{provider.upper()}"
        idea = make_idea(**raw)
        cost = 0.03 if provider in ("anthropic", "gemini", "openai") else 0.005
        return idea, provider, cost

    idea = synthesize_combinatorial_idea(existing_ids, existing_slugs, iteration)
    return idea, "synthesis", 0.0